// WF-02 | Stage 5 - Intent, Sentiment & RAG Knowledge Engine (Gemini 3.8 Flash)
const caller = $("02 Caller Identification").first().json;
const lead = $("03 Lookup Caller Lead").first()?.json || {};
const runRecord = $("04 Create Workflow Run").first().json;

const text = caller.speech_text.toLowerCase();
const ragContext = lead.rag_context || "Bảng giá AI Sales Agent: Gói Starter 2.000.000đ/tháng (CRM + Email Triage, tối đa 5 user); Gói Pro 5.000.000đ/tháng (Full 24 Workflows: Tổng đài Voice AI Outbound/Inbound, RAG pgvector, Multi-Agent Orchestrator, 20 user); Gói Enterprise 15.000.000đ/tháng (Self-host riêng, Custom Voice Cloning không giới hạn, SLA 99.9%). Chính sách: Dùng thử miễn phí 14 ngày, giảm tối đa 15% khi thanh toán theo năm.";

let intent = "general_faq";
let sentiment = "neutral";
let isEscalation = false;
let ragAnswer = "";

if (/gặp nhân viên|gặp tư vấn|nói chuyện với người|chuyển máy|khiếu nại|bực mình|lỗi nặng/i.test(text)) {
  intent = "speak_to_human";
  isEscalation = true;
  sentiment = /khiếu nại|bực mình|lỗi/i.test(text) ? "negative" : "neutral";
} else if (/giá|bảng giá|chi phí|gói|bao nhiêu tiền|báo giá|chiết khấu/i.test(text)) {
  intent = "pricing";
  sentiment = "positive";
  ragAnswer = "Dạ theo bảng giá chính thức của AI Sales Agent: Gói Starter là 2 triệu đồng/tháng, gói Pro đầy đủ Tổng đài Voice AI và RAG pgvector là 5 triệu đồng/tháng, và gói Enterprise là 15 triệu đồng/tháng. Đặc biệt bên em hỗ trợ dùng thử miễn phí 14 ngày và chiết khấu đến 15% khi đăng ký theo năm ạ.";
} else if (/tính năng|voice ai|tổng đài|chức năng|giải pháp|rag|crm/i.test(text)) {
  intent = "product_inquiry";
  sentiment = "positive";
  ragAnswer = "Dạ hệ thống AI Sales Agent tích hợp 24 Workflows tự động hóa: từ Tổng đài nghe gọi AI hai chiều (WF-01, WF-02), Nhạc trưởng điều phối tạo báo giá tự động (WF-03), tra cứu kho tri thức RAG pgvector (WF-09) đến đồng bộ CRM đa kênh ạ.";
} else {
  ragAnswer = "Dạ hệ thống AI Sales Agent bên em cung cấp giải pháp tự động hóa bán hàng B2B toàn diện với 3 gói Starter (2 triệu), Pro (5 triệu) và Enterprise (15 triệu/tháng) kèm 14 ngày dùng thử miễn phí ạ.";
}

const callerName = (lead.first_name && lead.first_name !== "Quý khách")
  ? (lead.first_name + " " + (lead.last_name || "")).trim()
  : (caller.caller_name_input || "Quý khách");

let geminiKey = "";
let geminiModel = "gemini-3.8-flash";
let llmModelUsed = "rag-postgres-local";
try {
  geminiKey = $env.GEMINI_API_KEY || "";
  geminiModel = $env.GEMINI_MODEL || "gemini-3.8-flash";
} catch (e) {}

if (geminiKey) {
  try {
    const prompt = "Bạn là Lễ tân Tổng đài AI (WF-02 Inbound Receptionist) của công ty AI Sales Agent.\n" +
      "Dữ liệu kiến thức RAG từ PostgreSQL pgvector:\n" + ragContext + "\n\n" +
      "Khách hàng (" + callerName + ") vừa gọi vào hỏi: \"" + caller.speech_text + "\"\n" +
      "Hãy phân tích và trả lời dựa đúng trên dữ liệu RAG (ngắn gọn 2-3 câu tự nhiên để đọc qua điện thoại). Nếu khách đòi gặp người thật hoặc khiếu nại gay gắt thì đặt is_escalation = true. Trả về đúng JSON:\n" +
      "{\"intent\": \"pricing|product_inquiry|speak_to_human|general_faq\", \"sentiment\": \"positive|neutral|negative\", \"is_escalation\": false, \"rag_answer\": \"Câu trả lời lễ tân AI\"}";
    const modelToUse = geminiModel || "gemini-3-flash-preview";
    const resp = await this.helpers.httpRequest({
      method: "POST",
      url: "https://generativelanguage.googleapis.com/v1beta/models/" + modelToUse + ":generateContent?key=" + geminiKey,
      headers: { "Content-Type": "application/json" },
      body: { contents: [{ parts: [{ text: typeof prompt !== "undefined" ? prompt : aiPrompt }] }] },
      json: true,
      timeout: 15000
    });
    const textOut = resp?.candidates?.[0]?.content?.parts?.[0]?.text || resp?.output_text || "";
    const jsonMatch = textOut.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.rag_answer) ragAnswer = parsed.ai_reply || parsed.rag_answer;
      if (parsed.intent) intent = parsed.intent;
      if (["positive", "neutral", "negative"].includes(parsed.sentiment)) sentiment = parsed.sentiment;
      if (typeof parsed.is_escalation === "boolean") isEscalation = parsed.is_escalation;
      llmModelUsed = geminiModel;
    }
  } catch (err) {}
}

return [{
  json: {
    workflow_run_id: runRecord.id,
    correlation_id: caller.correlation_id,
    call_sid: caller.call_sid,
    from_phone: caller.from_phone,
    lead_id: lead.id || null,
    caller_name: callerName,
    speech_text: caller.speech_text,
    voice_id: caller.voice_id,
    intent,
    sentiment,
    is_escalation: isEscalation,
    rag_answer: ragAnswer,
    llm_model: llmModelUsed
  }
}];

// WF-02 | Stage 7a - Generate Transfer TwiML (Chuyển máy tư vấn viên)
const item = $input.first().json;
const hotline = '+842471088888';

const speechResponse = `Dạ em xin phép chuyển cuộc gọi của anh/chị ${item.caller_name} tới chuyên viên hỗ trợ ngay ạ. Xin vui lòng giữ máy.`;
const twiml = `
<Response>
  <Say voice="Polly.Aditi" language="vi-VN">${speechResponse}</Say>
  <Dial timeout="20">${hotline}</Dial>
</Response>
`.trim();

return [{
  json: {
    ...item,
    action_taken: 'transferred_to_human',
    speech_response: speechResponse,
    twiml
  }
}];

// WF-02 | Stage 7b - Generate Direct RAG Voice Response
const item = $input.first().json;
const fullSpeech = item.rag_answer || ("Dạ em chào anh/chị " + item.caller_name + ". Giải pháp AI Sales Agent bên em có gói Starter 2 triệu và gói Pro 5 triệu/tháng ạ.");
const twiml = "<Response>\n  <Say voice=\"Polly.Aditi\" language=\"vi-VN\">" + fullSpeech + "</Say>\n  <Gather input=\"speech\" timeout=\"5\" language=\"vi-VN\">\n    <Say voice=\"Polly.Aditi\" language=\"vi-VN\">Anh chị cần hỗ trợ thêm thông tin gì nữa không ạ?</Say>\n  </Gather>\n</Response>";

return [{
  json: {
    ...item,
    action_taken: "resolved_by_ai_rag",
    speech_response: fullSpeech,
    twiml
  }
}];

